<script setup lang="ts">import {computed,onMounted} from 'vue';import {lots} from '../stores/lots';import {runs} from '../stores/runs';import PageHeading from '../components/common/PageHeading.vue';import AllocationTable from '../components/AllocationTable.vue';import QuotaBars from '../components/QuotaBars.vue';import {pct} from '../utils/format';onMounted(()=>Promise.all([lots.load(),runs.load()]));const result=computed(()=>(runs.items.value.find(r=>r.id==='demo-run')||runs.items.value.find(r=>r.status==='completed'))?.result);const size=computed(()=>lots.items.value.reduce((s,r)=>s+r.size,0))</script><template><PageHeading index="00 / 抽样总览" title="有限的复核预算，要有可追溯的分配。" note="先验证每个风险层的检出目标能否满足，再按Neyman权重分配整数配额，固定seed无放回抽取具体文档。"/><div v-if="result" class="overview-layout"><section><div class="ledger-heading"><h2>四层抽样 · 预算底稿</h2><router-link to="/allocation">查看计算过程 ↗</router-link></div><div class="metrics"><div><small>已入库档案</small><strong>{{size.toLocaleString()}}</strong><span>{{lots.items.value.length}} 个批次</span></div><div><small>复核预算</small><strong>{{result.budget}}</strong><span>最低需求 {{result.required_budget??'不可达'}}</span></div><div><small>层级检出目标</small><strong>{{pct(result.target)}}</strong><span>基于假设差错数 D</span></div></div><AllocationTable :rows="result.strata"/><p class="method-note">{{result.assumption}}</p></section><aside class="margin-note"><p class="eyebrow">SAMPLE ALLOCATION</p><h2>配额与最低需求</h2><QuotaBars :rows="result.strata"/><p>层内抽样不放回；每个文档编号至多出现一次。检出率不等于质量合格概率。</p></aside></div><section class="workflow-strip"><div><b>01 / 建底册</b><h3>批量、风险与差错率</h3><p>保留预估口径，区分假设与已测事实。</p></div><div><b>02 / 算预算</b><h3>不可行就明确停下</h3><p>预算不足或D=0，不生成伪达标清单。</p></div><div><b>03 / 留编号</b><h3>复核同一份文档</h3><p>固定seed、保存样本、批准后下载快照。</p></div></section></template>
